=== zimmSubscribeSection/index.stories.tsx ===
     1	import React from 'react';
     2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     3	import { ZimmSubscribeSection } from './index';
     4	
     5	const meta: Meta<typeof ZimmSubscribeSection> = {
     6	  title: 'Forms/ZimmSubscribeSection',
     7	  component: ZimmSubscribeSection,
     8	  // This organism's recipe hard-codes inverse (light-on-dark) colours with no light variant, so
     9	  // mounted in isolation on Storybook's white canvas its own text is unreadable and axe fails it:
    10	  // the `heading` part (--zimm-color-text-inverse-grey, #969696) came out at 2.95:1 against white,
    11	  // below the 4.5:1 AA floor for 12px/500. That's an artefact of the isolated mount, not a defect
    12	  // — in the footer this sits inside the `container` part, which is the only background in the
    13	  // chain (footer.css.ts:25, --zimm-color-bg-05 / #191919), where the same colour is 5.94:1 and
    14	  // passes. Worse, the `body` and input are --zimm-color-text-inverse (#ffffff), i.e. white on
    15	  // white at 1:1 — invisible, and axe did not even report those. This decorator reproduces the
    16	  // shipped background so the a11y check measures the context the component actually renders in.
    17	  decorators: [
    18	    (Story) => (
    19	      <div style={{ backgroundColor: 'var(--zimm-color-bg-05)', padding: 'var(--zimm-scale-2xl)' }}>
    20	        <Story />
    21	      </div>
    22	    ),
    23	  ],
    24	  // No canvas-background setting here on purpose. A `parameters: {backgrounds: {default: 'dark'}}`
    25	  // used to sit at this spot and was a silent no-op — Storybook 10 reads the selection from
    26	  // `globals.backgrounds.value`, and nothing reads `parameters…default` — which is part of why the
    27	  // a11y failure surfaced. The obvious repair, `globals: {backgrounds: {value: 'dark'}}`, was
    28	  // rejected: Storybook's built-in `dark` is #333 against this decorator's #191919, so it would
    29	  // introduce a second, underived dark that can drift from the token. The decorator is the only
    30	  // surface axe or the eye needs.
    31	  args: {
    32	    heading: 'Keep in touch',
    33	    body: 'Be the first to know about new collections and new arrivals.',
    34	    privacyPolicyHref: '/privacy-policy',
    35	  },
    36	};
    37	export default meta;
    38	type Story = StoryObj<typeof ZimmSubscribeSection>;
    39	
    40	export const Default: Story = {};
    41	
    42	export const Subscribed: Story = {
    43	  args: { initialSubscribed: true },
    44	};
    45	
    46	/**
    47	 * Full email → modal → submit interaction coverage (including the a11y/focus assertions) lives
    48	 * at the footer assembly level — footer/index.stories.tsx's SubscribeSubmit and
    49	 * SubscribeModalOpen — since that's the shipped context and testing.md says prove behaviour
    50	 * once, at the cheapest layer. These stories exist for components.md's per-exported-component
    51	 * requirement and for visual variants when this organism is placed elsewhere.
    52	 */
    53	export const NameCaptureEnabled: Story = {
    54	  name: 'Name capture modal enabled (HPC-035, not shipped)',
    55	  args: { enableNameCapture: true },
    56	};

