/** Exactly what zimmSubscribeModal/index.stories.tsx renders today (mounted flips in an effect). */
export const OrganismOnly: Story = {
  render: () => {
    const [isOpen, setIsOpen] = useState(true);
    return (
      <ZimmSubscribeModal
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
        onSubmit={() => setIsOpen(false)}
        privacyPolicyHref="/privacy-policy"
      />
    );
  },
  play: async ({ canvasElement }: { canvasElement: HTMLElement }) => {
    const canvas = within(canvasElement);
    const doc = within(document.body);
    // Establish the portal really did arrive, body-scoped, before measuring canvas scope.
    await doc.findByRole('dialog');
    const dialog = document.body.querySelector('[role="dialog"]');
    window.__PROBE__ = {
      story: 'OrganismOnly',
      canvasElement: { tagName: canvasElement.tagName, id: canvasElement.id, chain: chainOf(canvasElement) },
      dialogsInDocument: document.body.querySelectorAll('[role="dialog"]').length,
      dialogsInsideCanvas: canvasElement.querySelectorAll('[role="dialog"]').length,
      dialogChain: chainOf(dialog),
      canvasContainsDialog: dialog ? canvasElement.contains(dialog) : null,
      canvasInnerHTMLLength: canvasElement.innerHTML.length,
      canvasInnerHTML: canvasElement.innerHTML.slice(0, 200),
      attempts: [
        await attempt('CR#4 VERBATIM  within(canvasElement).findByRole("dialog")', () =>
          canvas.findByRole('dialog'),
