        await attempt('CR#4 VERBATIM  within(canvasElement).findByRole("link",{name:/privacy policy/i})', () =>
          canvas.findByRole('link', { name: /privacy policy/i }),
        ),
        await attempt('SHIPPED TODAY within(document.body).findByRole("dialog")', () => doc.findByRole('dialog')),
        await attempt('SHIPPED TODAY within(document.body).findByRole("heading",{name:/join us/i})', () =>
          doc.findByRole('heading', { name: /join us/i }),
        ),
      ],
    };
  },
};

/** Does a story-local portal target inside canvasElement make canvas-scoped queries work?
 *  (Hand-rolled: ZimmModal hardcodes document.body and exposes no container prop.) */
export const StoryLocalPortalTarget: Story = {
  render: () => {
    const hostRef = useRef<HTMLDivElement>(null);
    const [ready, setReady] = useState(false);
    useEffect(() => setReady(true), []);
    return (
      <div>
        <div ref={hostRef} data-probe-host />
        {ready && hostRef.current
          ? createPortal(<div role="dialog" aria-modal="true" aria-label="story-local portal" />, hostRef.current)
          : null}
