      story: 'StoryLocalPortalTarget',
      dialogChain: chainOf(dialog),
      canvasContainsDialog: dialog ? canvasElement.contains(dialog) : null,
      attempts: [
        await attempt('within(canvasElement).findByRole("dialog")', () => canvas.findByRole('dialog')),
      ],
    };
  },
};
